    "source": "def get_version():
    import configparser
    import pathlib

    config_parser = configparser.ConfigParser()
    file_path = pathlib.Path(__file__)
    parent_dir = file_path.parent
    grandparent_dir = parent_dir.parent
    setup_cfg_path = grandparent_dir / "setup.cfg"
    config_parser.read(str(setup_cfg_path))
    metadata_section = config_parser["metadata"]
    version_value = metadata_section["version"]
    return version_value"
