    "qualname": "src/cachetools/__init__.py::Cache.__setitem__",
    "source": "def __setitem__(self, key, value):
    max_allowed_size = self.__maxsize
    item_size = self.getsizeof(value)
    if item_size > max_allowed_size:
        raise ValueError("value too large")

    current_data = self.__data
    current_sizes = self.__size
    current_total_size = self.__currsize

    needs_eviction = False
    if key not in current_data or current_sizes[key] < item_size:
        while current_total_size + item_size > max_allowed_size:
            self.popitem()
            # Refresh references after popitem might have changed state
            current_total_size = self.__currsize

    diff_size = 0
    if key in current_data:
        old_size = current_sizes[key]
        diff_size = item_size - old_size
    else:
        diff_size = item_size

    self.__data[key] = value
    self.__size[key] = item_size
    self.__currsize += diff_size"
