    "source": "def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    order_list = self.__order
    try:
        iterator = iter(order_list)
        oldest_key = next(iterator)
    except StopIteration:
        class_name = type(self).__name__
        error_msg = "%s is empty" % class_name
        raise KeyError(error_msg) from None
    else:
        removed_value = self.pop(oldest_key)
        return (oldest_key, removed_value)"
