    "qualname": "src/cachetools/__init__.py::TTLCache.__getitem__",
    "source": "def __getitem__(self, key, cache_getitem=Cache.__getitem__):
    link_node = None
    expired_flag = False
    try:
        link_node = self.__getlink(key)
    except KeyError:
        expired_flag = False
    else:
        current_time = self.__timer()
        expire_time = link_node.expire
        expired_flag = not (current_time < expire_time)

    if expired_flag:
        return self.__missing__(key)
    else:
        return cache_getitem(self, key)"
