    "qualname": "src/cachetools/__init__.py::TTLCache.__setitem__",
    "source": "def __setitem__(self, key, value, cache_setitem=Cache.__setitem__):
    with self.__timer as current_time:
        self.expire(current_time)
        cache_setitem(self, key, value)

    link_node = None
    try:
        link_node = self.__getlink(key)
    except KeyError:
        new_link = _Link(key)
        self.__links[key] = new_link
        link_node = new_link
    else:
        link_node.unlink()

    ttl_duration = self.__ttl
    link_node.expire = current_time + ttl_duration

    root_node = self.__root
    prev_node = root_node.prev

    link_node.next = root_node
    link_node.prev = prev_node
    prev_node.next = link_node
    root_node.prev = link_node"
