    "qualname": "src/cachetools/__init__.py::TTLCache.__setstate__",
    "source": "def __setstate__(self, state):
    self.__dict__.update(state)
    root_node = self.__root
    root_node.prev = root_node
    root_node.next = root_node

    links_values = self.__links.values()
    sorted_links = sorted(links_values, key=lambda obj: obj.expire)
    for link_node in sorted_links:
        link_node.next = root_node
        prev_node = root_node.prev
        link_node.prev = prev_node
        prev_node.next = link_node
        root_node.prev = link_node

    current_time = self.__timer()
    self.expire(current_time)"
