    "qualname": "src/cachetools/__init__.py::TTLCache.expire",
    "source": "def expire(self, time=None):
    """Remove expired items from the cache."""
    if time is None:
        time = self.__timer()

    root_node = self.__root
    current_node = root_node.next
    links_dict = self.__links
    del_item_method = Cache.__delitem__

    while current_node is not root_node:
        expire_time = current_node.expire
        if not (time < expire_time):
            break

        del_item_method(self, current_node.key)
        del links_dict[current_node.key]

        next_node = current_node.next
        current_node.unlink()
        current_node = next_node"
