    "qualname": "src/cachetools/func.py::_cache",
    "source": "def _cache(cache, typed):
    maxsize_val = cache.maxsize

    def decorator(func):
        if typed:
            key_func = keys.typedkey
        else:
            key_func = keys.hashkey
        lock_obj = RLock()
        stats_list = [0, 0]

        def wrapper(*args, **kwargs):
            k = key_func(*args, **kwargs)
            with lock_obj:
                try:
                    v = cache[k]
                    stats_list[0] += 1
                    return v
                except KeyError:
                    stats_list[1] += 1
            v = func(*args, **kwargs)
            # in case of a race, prefer the item already in the cache
            try:
                with lock_obj:
                    return cache.setdefault(k, v)
            except ValueError:
                return v  # value too large

        def cache_info():
            with lock_obj:
                hits_count = stats_list[0]
                misses_count = stats_list[1]
                maxsize_current = cache.maxsize
                currsize_current = cache.currsize
            return _CacheInfo(hits_count, misses_count, maxsize_current, currsize_current)

        def cache_clear():
            with lock_obj:
                try:
                    cache.clear()
                finally:
                    stats_list[0] = 0
                    stats_list[1] = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.cache_parameters = lambda: {"maxsize": maxsize_val, "typed": typed}
        functools.update_wrapper(wrapper, func)
        return wrapper

    return decorator"
