    "source": "def fifo_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a First In First Out (FIFO)
    algorithm.

    """
    if maxsize is None:
        unbound_cache = _UnboundCache()
        return _cache(unbound_cache, typed)
    elif callable(maxsize):
        default_fifo = FIFOCache(128)
        decorated_func = _cache(default_fifo, typed)(maxsize)
        return decorated_func
    else:
        specific_fifo = FIFOCache(maxsize)
        return _cache(specific_fifo, typed)"
