    "qualname": "src/cachetools/keys.py::typedkey",
    "source": "def typedkey(*args, **kwargs):
    """Return a typed cache key for the specified hashable arguments."""
    base_key = hashkey(*args, **kwargs)
    arg_types = tuple(type(v) for v in args)
    base_key = base_key + arg_types
    kwarg_items = sorted(kwargs.items())
    kwarg_types = tuple(type(v) for _, v in kwarg_items)
    base_key = base_key + kwarg_types
    return base_key"
